const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

const rootDir = path.resolve(__dirname, '..');
const distAssets = path.join(rootDir, 'dist', 'assets');
const distElectronMain = path.join(rootDir, 'dist-electron', 'main.cjs');
// The stdio bridge is generated by build:electron and shipped with the app, so
// a stale dist-electron without it would hand clients a broken config path.
const distElectronBridge = path.join(rootDir, 'dist-electron', 'mcp-bridge.cjs');

if (!fs.existsSync(distAssets) || !fs.existsSync(distElectronMain) || !fs.existsSync(distElectronBridge)) {
  console.log('[ensure-build-artifacts] Production artifacts missing, executing npm run build...');
  execSync('npm run build', { cwd: rootDir, stdio: 'inherit' });
}
